package access

//go:generate go run ./gen/aws -out data

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"fmt"
	"slices"
	"strings"
	"sync"

	"github.com/ismaelosuna7824/nimbo/backend/internal/model"
)

// AWS reference data: the AWS Service Authorization Reference (every
// service prefix, its actions with their access level and resource types),
// generated by gen/aws from the machine-readable service reference AWS
// publishes and pinned here with its retrieval date.

//go:embed data/aws.json.gz
var awsSARGzip []byte

// AWSService is one service of the Service Authorization Reference.
type AWSService struct {
	Prefix    string           `json:"prefix"`
	Name      string           `json:"name"`
	Version   string           `json:"version,omitempty"`
	Resources []AWSResourceSAR `json:"resources,omitempty"`
	Actions   []AWSActionSAR   `json:"actions"`
}

// AWSResourceSAR is a resource type of a service with its ARN formats.
type AWSResourceSAR struct {
	Name string   `json:"name"`
	ARNs []string `json:"arns,omitempty"`
}

// AWSActionSAR is an action (without the service prefix), its access level
// ("List", "Read", "Write", "Permissions management", "Tagging") and the
// resource types it can be scoped to (none: it only supports "*").
type AWSActionSAR struct {
	Name      string   `json:"name"`
	Level     string   `json:"level"`
	Resources []string `json:"resources,omitempty"`
}

type awsSARFile struct {
	Source   model.AccessSource `json:"source"`
	Services []AWSService       `json:"services"`
}

type awsSARIndex struct {
	file     awsSARFile
	byPrefix map[string]*AWSService
	// actions maps lower-case "prefix:action" to its service and action.
	actions map[string]awsActionRef
}

type awsActionRef struct {
	svc *AWSService
	act *AWSActionSAR
}

var awsSAR = sync.OnceValues(func() (*awsSARIndex, error) {
	zr, err := gzip.NewReader(bytes.NewReader(awsSARGzip))
	if err != nil {
		return nil, fmt.Errorf("access: aws reference data: %w", err)
	}
	defer zr.Close()
	idx := &awsSARIndex{byPrefix: map[string]*AWSService{}, actions: map[string]awsActionRef{}}
	if err := json.NewDecoder(zr).Decode(&idx.file); err != nil {
		return nil, fmt.Errorf("access: aws reference data: %w", err)
	}
	for i := range idx.file.Services {
		s := &idx.file.Services[i]
		idx.byPrefix[s.Prefix] = s
		for j := range s.Actions {
			idx.actions[strings.ToLower(s.Prefix+":"+s.Actions[j].Name)] = awsActionRef{s, &s.Actions[j]}
		}
	}
	return idx, nil
})

// AWSSARSource cites the pinned AWS reference data.
func AWSSARSource() model.AccessSource {
	idx, err := awsSAR()
	if err != nil {
		return model.AccessSource{}
	}
	return idx.file.Source
}

// AWSServiceByPrefix returns a service of the reference ("dynamodb").
func AWSServiceByPrefix(prefix string) (*AWSService, bool) {
	idx, err := awsSAR()
	if err != nil {
		return nil, false
	}
	s, ok := idx.byPrefix[prefix]
	return s, ok
}

// AWSAction looks an action up ("dynamodb:GetItem", case-insensitive).
func AWSAction(name string) (AWSActionSAR, bool) {
	idx, err := awsSAR()
	if err != nil {
		return AWSActionSAR{}, false
	}
	r, ok := idx.actions[strings.ToLower(name)]
	if !ok {
		return AWSActionSAR{}, false
	}
	return *r.act, true
}

// normResource folds a resource type name for loose matching
// ("state_machine", "stateMachine" and "state-machine" match).
func normResource(s string) string {
	return strings.NewReplacer("-", "", "_", "", " ", "").Replace(strings.ToLower(s))
}

// ResourceType returns the reference's resource type of s named like
// name, ignoring case, dashes and underscores.
func (s *AWSService) ResourceType(name string) (string, bool) {
	want := normResource(name)
	for _, r := range s.Resources {
		if normResource(r.Name) == want {
			return r.Name, true
		}
	}
	return "", false
}

// ActionsOn returns the full action names ("sqs:SendMessage") of s that
// can be scoped to resourceType and whose level is one of levels (all
// levels when empty), sorted.
func (s *AWSService) ActionsOn(resourceType string, levels ...string) []string {
	var out []string
	for _, a := range s.Actions {
		if !slices.Contains(a.Resources, resourceType) {
			continue
		}
		if len(levels) > 0 && !slices.Contains(levels, a.Level) {
			continue
		}
		out = append(out, s.Prefix+":"+a.Name)
	}
	slices.Sort(out)
	return out
}

func init() {
	RegisterCatalog("aws", awsCatalog)
}

// awsCatalog serves the services (no ?service=) or the actions of one
// service, filtered by ?q= (substring of prefix, name or action).
func awsCatalog(q CatalogQuery) (*model.AccessCatalog, error) {
	idx, err := awsSAR()
	if err != nil {
		return nil, err
	}
	out := &model.AccessCatalog{Provider: "aws", Source: idx.file.Source}
	search := strings.ToLower(strings.TrimSpace(q.Search))
	if q.Service == "" {
		out.Services = make([]model.AccessService, 0, len(idx.file.Services))
		for _, s := range idx.file.Services {
			if search != "" && !strings.Contains(strings.ToLower(s.Prefix), search) && !strings.Contains(strings.ToLower(s.Name), search) {
				continue
			}
			out.Services = append(out.Services, model.AccessService{Prefix: s.Prefix, Name: s.Name})
		}
		return out, nil
	}
	s, ok := idx.byPrefix[strings.ToLower(strings.TrimSpace(q.Service))]
	if !ok {
		return nil, Editf("access: unknown AWS service prefix %q", q.Service)
	}
	out.Services = []model.AccessService{{Prefix: s.Prefix, Name: s.Name}}
	out.Actions = make([]model.AccessAction, 0, len(s.Actions))
	for _, a := range s.Actions {
		name := s.Prefix + ":" + a.Name
		if search != "" && !strings.Contains(strings.ToLower(name), search) {
			continue
		}
		out.Actions = append(out.Actions, model.AccessAction{Name: name, Level: a.Level, ResourceTypes: a.Resources})
	}
	return out, nil
}
